// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AIProvider) predicate.AIProvider {
	return predicate.AIProvider(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AIProvider) predicate.AIProvider {
	return predicate.AIProvider(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AIProvider) predicate.AIProvider {
	return predicate.AIProvider(sql.NotPredicates(p))
}
